function glassLevel(poured: number, row: number, glass: number): number {
  const flow: number[][] = Array.from({ length: row + 1 }, (_, i) => new Array(i + 1).fill(0));
  flow[0][0] = poured;
  for (let i = 0; i < row; i++) {
    for (let j = 0; j <= i; j++) {
      const extra = (flow[i][j] - 1) / 2;
      if (extra > 0) {
        flow[i + 1][j] += extra;
        flow[i + 1][j + 1] += extra;
      }
    }
  }
  return Math.min(1, flow[row][glass]);
}

